import 'dart:async';

import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_soloud/flutter_soloud.dart';

import 'settings.dart';

/// Sound effects (generated by tools/make_sfx.py) and background music
/// (recorded tracks from Pixabay, see README.md).
/// Uses SoLoud for low latency and many overlapping sounds. If audio cannot
/// start on a device, the game simply stays silent.
class Sfx {
  Sfx(this._settings);

  final Settings _settings;
  final _sources = <String, AudioSource>{};
  bool _ready = false;
  final _songs = <int, AudioSource>{};
  var _song = 0;
  SoundHandle? _musicHandle;
  bool _hidden = false;

  static const _musicVolume = 0.15;

  /// The songs play in this order, then start over: calm, then the long
  /// one, then the bright one. `start` and `end` (seconds) skip the silence
  /// at each edge so one song flows straight into the next, and `gain`
  /// evens out their loudness (measured from the files).
  static const _playlist = [
    (file: 'chill_music_loop.mp3', gain: 1.1, start: 0.0, end: 36.3),
    (file: 'video_game_music.mp3', gain: 0.95, start: 0.45, end: 424.7),
    (file: 'puzzle_game_music.mp3', gain: 0.62, start: 0.1, end: 75.4),
  ];

  /// How long the end of one song and the start of the next overlap.
  static const _overlap = Duration(milliseconds: 500);

  static const popSteps = 8;
  static final _names = [
    for (var i = 0; i < popSteps; i++) 'pop_$i',
    'land', 'crack', 'rise', 'deny', 'tap', 'praise', 'levelup', 'newbest', 'gameover',
  ];

  Future<void> init() async {
    try {
      final soloud = SoLoud.instance;
      if (!soloud.isInitialized) await soloud.init(bufferSize: 1024);
      for (final name in _names) {
        _sources[name] = await soloud.loadAsset('assets/sfx/$name.wav');
      }
      _ready = true;
      _settings.addListener(_syncMusic);
      // Music pauses while the app is in the background.
      AppLifecycleListener(
        onHide: () => _setHidden(true),
        onShow: () => _setHidden(false),
      );
      unawaited(_loadSongs());
      Timer.periodic(const Duration(milliseconds: 100), (_) => _watchSong());
    } catch (e) {
      debugPrint('Audio unavailable, continuing without sound: $e');
    }
  }

  /// Loads the songs in order; music starts as soon as the first is ready.
  Future<void> _loadSongs() async {
    for (var i = 0; i < _playlist.length; i++) {
      try {
        // Songs stream from disk where possible, so they don't sit decoded
        // in memory.
        _songs[i] = await SoLoud.instance
            .loadAsset('assets/music/${_playlist[i].file}', mode: kIsWeb ? LoadMode.memory : LoadMode.disk);
        if (_songs.length == 1) {
          _song = i;
          _syncMusic();
        }
      } catch (e) {
        debugPrint('Could not load music ${_playlist[i].file}: $e');
      }
    }
  }

  int _nextSong(int i) {
    for (var k = 1; k <= _playlist.length; k++) {
      final j = (i + k) % _playlist.length;
      if (_songs.containsKey(j)) return j;
    }
    return i;
  }

  /// Near the end of a song, fades it out while the next one starts.
  void _watchSong() {
    final h = _musicHandle;
    if (h == null) return;
    final soloud = SoLoud.instance;
    try {
      if (!soloud.getIsValidVoiceHandle(h)) {
        _musicHandle = null;
        _song = _nextSong(_song);
        _syncMusic();
        return;
      }
      if (soloud.getPause(h)) return;
      final end = _playlist[_song].end - _overlap.inMilliseconds / 1000;
      if (soloud.getPosition(h).inMilliseconds / 1000 < end) return;
      soloud.fadeVolume(h, 0, _overlap);
      soloud.scheduleStop(h, _overlap);
      _song = _nextSong(_song);
      _startSong(_overlap);
    } catch (e) {
      debugPrint('Could not update music: $e');
    }
  }

  void _startSong(Duration fadeIn) {
    final soloud = SoLoud.instance;
    final song = _playlist[_song];
    final h = soloud.play(_songs[_song]!, volume: 0, paused: true);
    if (song.start > 0) soloud.seek(h, Duration(milliseconds: (song.start * 1000).round()));
    soloud.setPause(h, false);
    soloud.fadeVolume(h, _musicVolume * song.gain, fadeIn);
    _musicHandle = h;
  }

  void _setHidden(bool hidden) {
    _hidden = hidden;
    _syncMusic();
  }

  /// Starts, pauses or resumes the music to match the setting.
  void _syncMusic() {
    if (!_songs.containsKey(_song)) return;
    final want = _settings.music && !_hidden;
    final soloud = SoLoud.instance;
    try {
      final handle = _musicHandle;
      if (handle == null || !soloud.getIsValidVoiceHandle(handle)) {
        if (want) _startSong(const Duration(seconds: 3));
      } else if (soloud.getPause(handle) == want) {
        if (want) {
          soloud.setVolume(handle, 0);
          soloud.setPause(handle, false);
          soloud.fadeVolume(handle, _musicVolume * _playlist[_song].gain, const Duration(seconds: 1));
        } else {
          soloud.setPause(handle, true);
        }
      }
    } catch (e) {
      debugPrint('Could not update music: $e');
    }
  }

  void _play(String name, {double volume = 1}) {
    if (!_ready || !_settings.sound) return;
    final source = _sources[name];
    if (source == null) return;
    try {
      SoLoud.instance.play(source, volume: volume);
    } catch (e) {
      debugPrint('Could not play $name: $e');
    }
  }

  /// Balls popping play the two rising kalimba notes, and a new row rising
  /// plays the soft droplet pop (swapped at the player's request).
  void pop(int step, {int groups = 1}) => _play('rise', volume: groups > 1 ? 0.8 : 0.7);
  void land() => _play('land', volume: 0.7);
  void crack() => _play('crack', volume: 0.8);
  void rise() => _play('pop_0', volume: 0.9);
  void deny() => _play('deny', volume: 0.6);
  void tap() => _play('tap', volume: 0.6);
  void praise() => _play('praise', volume: 0.8);
  void levelUp() => _play('levelup', volume: 0.8);
  void newBest() => _play('newbest');
  void gameOver() => _play('gameover', volume: 0.8);
}
